DISTANCES=(10,100,500,1000,1500,2000)
def guided(a):return any(x in a['type'].upper() for x in ('ATGM','SAM','AAM'))
def chemical(a):return not a.get('kinetic_missile') and any(x in a['type'].upper() for x in ('HEAT','ATGM','SAM','HESH'))
def explosive(a):
 if a.get('kinetic_missile'):return False
 t=a.get('effect_type',a['type']).upper()
 return chemical(a) or 'HE' in t or 'APHE' in t or 'APCBC' in t

def penetration_at(a,distance):
 values=a['penetration']
 if chemical(a):return values[0]
 if distance<=10:return values[0]
 for i in range(1,len(DISTANCES)):
  if distance<=DISTANCES[i]:
   f=(distance-DISTANCES[i-1])/(DISTANCES[i]-DISTANCES[i-1])
   return values[i-1]+(values[i]-values[i-1])*f
 return max(0,values[-1]-(distance-2000)*max(0,values[-2]-values[-1])/500)

def configure(v):
 d=DATA[v['id']];v['research_data']=d;v['rank']=d['rank'];v['br']=d['br']
 if v['id']=='cn_2_4':
  v['name']='WZ141-1';v['model']=(37,17,'open',0,12,46);v['wheel']=False;v['barrels']=2;v['mg']=True
 if v['id']=='us_2_7':v['name']='M113A1 TOW'
 v['grenade']=d.get('grenade');v['missile_capacity']=d.get('missile_capacity');v['aps']=d.get('aps');v['aps_charges']=8 if v['aps'] else 0
 if 'traits' in d:
  v.update(d['traits']);v['equipment']=[label for key,label in [('mg','机枪'),('night','夜视'),('thermal','热成像'),('dual','双流传动')] if v[key]]
  if v['stabilizer']:v['equipment'].append('双向稳定' if v['stabilizer']==2 else '单向稳定')
 if v['aps']:v['equipment'].append(v['aps']+' 主动防御')
 if v['grenade']:v['equipment'].append('双榴弹发射器')
 if v['name'] in ('BMPT','BMPT-72'):v['equipment'].append('双30mm机炮')
 v['weight']=d['weight'];v['horsepower']=d['hp'];v['power_weight']=d['hp']/d['weight']
 v['forward_kph']=d['forward'];v['reverse_kph']=d['reverse']
 v['speed']=d['forward']*5;v['reverse']=d['reverse']*5
 v['armor']=tuple(d['hull']);v['turret_armor']=tuple(d.get('turret',d['hull']))
 profile=FRONT_PROFILES.get(v['id'],{})
 v['front_profile']=profile
 v['turret_slew']=profile.get('slew',d.get('slew',28))
 v['turret_slew_basis']=profile.get('slew_basis','原资料 / 模拟参数')
 # Conversion to this top-down game is intentionally simplified; degrees/s are simulation parameters.
 v['turn']=1.30*max(28,min(90,35+v['power_weight']*1.3))*(.82 if v['wheel'] else 1)
 v['steering_acceleration']=max(65,min(240,55+v['power_weight']*4))
 v['acceleration']=max(10,min(45,6+v['power_weight']*.8))
 v['steering']='车轮转向' if v['wheel'] else '双流传动 / 中心转向' if v['dual'] else '差速 / 制动转向'
 options=d['ammo']+d['secondary'];v['ammo_options']=options
 primary=d['ammo'];first=primary[0]
 caliber=re.search(r'(\d+(?:\.\d+)?)\s*mm',d['primary_weapon_name'])
 for shell in d['ammo']:
  if caliber:shell['caliber']=float(caliber[1])
 for shell in d['secondary']:shell.setdefault('caliber',150.)
 v['weapon']='sam' if all(guided(a) for a in primary) else 'auto' if d.get('rpm') else 'gun'
 v['missile']=any(guided(a) for a in options)
 v['missile_ground']=v['missile'] and v['branch']!=3
 v['independent_missiles']=d['independent_missiles']
 barrels=re.match(r'(\d+) x ',d['primary_weapon_name'])
 if barrels:v['barrels']=int(barrels.group(1))
 v['missile_reload']=d['missile_reload']
 v['smoke_grenades']=d['smoke_grenades'];v['ess']=d['ess']
 if v['smoke_grenades']:v['equipment'].append('烟雾弹')
 if v['ess']:v['equipment'].append('发动机烟幕')
 # Autocannon RPM is per barrel; every simulated shot represents one barrel firing.
 v['reload']=60/d['rpm'] if v['weapon']=='auto' else d.get('reload',10)
 v['ammo_reload']=d.get('reload',10)
 if v['mg'] and '机枪' not in v['equipment']:v['equipment'].insert(0,'机枪')
 if v['missile'] and not any('导弹' in e for e in v['equipment']):v['equipment'].append('导弹')
 v['pen']=options[default_ammo(v)]['penetration'][0]
 v['composite']=d['composite'];v['era']=d['era']
 v['armor_note']='WT 基础装甲厚度；复合结构防护为简化模拟' if d['composite'] else 'WT 公布的基础装甲厚度'
 v['steering_note']='传动类别与功重比驱动转向；具体角速度为本游戏模拟'
 # A 2D impact cannot represent the full layered 3D WT armour mesh.
 # Only the 2A7V frontal hull effective values below are quoted from the linked WT article.
 v['effective_front']=None
 if v['id']=='de_1_10':v['effective_front']=(580,1200)
 v['armor_reference']='https://wiki.warthunder.com/5600-leopard-2a7v-punchy-fast-deadly' if v['effective_front'] else d['source']
 from TurretResponse import configure as response
 response(v)

def default_ammo(v):
 return next((i for i,a in enumerate(v['ammo_options']) if a['type'] in ('APFSDS','APDS','APHE','APCBC','AP')),0)

def ammo_name(a):return a['name']+' · '+('动能导弹 / 驾束制导' if a.get('kinetic_missile') else a['type'])
